<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Blends & Rituals — {{BUSINESS_NAME}}</title>
<style>
:root{--brand:#5a412f;--accent:#c98f4b;--muted:#6d6d6d;background:#fffefb}
*{box-sizing:border-box}
body{font-family:Georgia,serif,Times,serif;margin:0;color:#262626;background:var(--background)}
.header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid rgba(0,0,0,0.04)}
.logoBox{display:flex;align-items:center;gap:12px}
.logoMark{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--brand),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
nav a{margin-left:12px;text-decoration:none;color:var(--muted);font-weight:600}
.hero{position:relative;padding:40px 22px;display:flex;gap:20px;align-items:flex-start}
.pattern-svg{position:absolute;left:-80px;top:-40px;opacity:0.07;width:420px;height:420px}
.hero .lead{max-width:68%}
.lead h1{margin:0;color:var(--brand);font-size:30px}
.lead p{color:#555;margin-top:10px}
.sideCard{background:white;padding:16px;border-radius:12px;box-shadow:0 8px 22px rgba(30,24,20,0.06)}
.blend-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;padding:22px}
.blend{background:#fff;border-radius:12px;padding:14px;border:1px solid rgba(0,0,0,0.03)}
.blend h3{margin:0 0 6px 0}
.blend p{margin:0;color:var(--muted);font-size:14px}
.cta{display:inline-block;margin-top:10px;background:var(--brand);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none}
.section{padding:18px 22px}
.proof{display:flex;gap:18px;align-items:flex-start}
.testimonial{flex:1;background:white;padding:14px;border-radius:10px;box-shadow:0 6px 18px rgba(30,24,20,0.05)}
.t-controls{display:flex;gap:8px;align-items:center;margin-top:10px}
.t-dot{width:10px;height:10px;border-radius:50%;background:#e6e6e6}
.t-dot.active{background:var(--accent)}
.badges{display:flex;gap:10px;flex-direction:column}
.badge{background:#fff2e8;color:var(--brand);padding:8px;border-radius:8px;position:relative}
.tooltip{position:absolute;left:110%;top:50%;transform:translateY(-50%);background:#222;color:#fff;padding:8px;border-radius:6px;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .15s}
.badge:hover .tooltip{opacity:1}
.small{font-size:13px;color:var(--muted)}
</style>
</head>
<body>
<header class="header">
<div class="logoBox">
<div class="logoMark">B</div>
<div>
<div style="font-weight:700">{{BUSINESS_NAME}}</div>
<div class="small">Careful blends, simple ritual prompts</div>
</div>
</div>
<nav>
<a href="index.html">Home</a>
<a href="services.html">Offerings</a>
<a href="blends.html">Blends</a>
<a href="shop.html">Shop</a>
<a href="about.html">About</a>
<a href="book.html">Reserve</a>
<a href="contact.html">Contact</a>
</nav>
</header>

<main>
<section class="hero">
<svg class="pattern-svg" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
<defs>
<linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#c98f4b"/><stop offset="1" stop-color="#5a412f"/></linearGradient>
<pattern id="p1" x="0" y="0" width="20" height="20" patternUnits="userSpaceOnUse">
<rect width="20" height="20" fill="white"/>
<circle cx="5" cy="5" r="2" fill="url(#g1)"/>
</pattern>
</defs>
<rect width="200" height="200" fill="url(#p1)" opacity="0.95"/>
</svg>
<div class="lead">
<h1>Blends crafted for small moments that may support gentle shifts</h1>
<p>Each blend is compositioned with safety in mind: thoughtful dilutions, clear usage notes, and scent stories to help you bring a small, repeatable ritual into your day.</p>
<a class="cta" href="shop.html">Explore the boutique</a>
</div>
<aside class="sideCard">
<strong>Need a custom blend?</strong>
<p class="small" style="margin-top:8px">I create home blends for people seeking a scent to use with mindful pauses. Consultations include dilution guidance and a patch test plan.</p>
<a class="cta" style="display:inline-block;margin-top:10px" href="{{PRIMARY_CTA_URL}}">Request a consult</a>
</aside>
</section>

<section class="section">
<div class="blend-list">
<div class="blend">
<h3>Morning Clarity</h3>
<p>Bright citrus with a grounding base. May support gentle focus during morning routines.</p>
</div>
<div class="blend">
<h3>Evening Ease</h3>
<p>Soft floral and resin to encourage ritualized winding-down practices.</p>
</div>
<div class="blend">
<h3>Transit Calm</h3>
<p>Mint and cedar for short, portable refreshes between tasks or travel.</p>
</div>
</div>
</section>

<section class="section">
<div style="display:flex;gap:20px;align-items:flex-start">
<div class="proof">
<div class="testimonial card" id="testimonial">
<blockquote id="quote" style="margin:0;font-style:italic;color:#3b3b3b">"The Evening Ease blend became a quiet anchor — I reach for it before bedtime and the ritual helps me slow down."</blockquote>
<div class="t-controls" aria-hidden>
<div id="dots"></div>
</div>
</div>

<div class="badges">
<div class="badge">Member — Aromatic Guild<div class="tooltip">Ongoing ethics and safety learning verified.</div></div>
<div class="badge">Reviewed in local wellness guide<div class="tooltip">Credibility note: community-curated review.</div></div>
</div>
</div>
</section>

<section class="section">
<div class="card" style="padding:16px;border-radius:10px">
<h3 style="margin-top:0">Proof gallery</h3>
<p class="small">Testimonials rotate automatically. Badges include concise context on hover.</p>
</div>
</section>

<footer style="padding:20px 22px;color:#666;border-top:1px solid rgba(0,0,0,0.04)">
<div>Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}</div>
<div style="margin-top:6px">Serving {{CITY}}, {{STATE}}</div>
</footer>

<script>
// Proof Gallery: rotating testimonials + badge tooltips are CSS hover based above.
(function(){
const testimonials=[
{"text":"The Evening Ease blend became a quiet anchor — I reach for it before bedtime and the ritual helps me slow down.","who":"— M"},
{"text":"Morning Clarity is bright without being sharp. It helps me get started without overstimulating.","who":"— S"},
{"text":"I ordered a small custom blend; the instructions included a patch test and dilution notes that felt very reassuring.","who":"— R"}
];
let idx=0;
const quote=document.getElementById('quote');
const dotsContainer=document.getElementById('dots');
function renderDots(){dotsContainer.innerHTML='';testimonials.forEach((t,i)=>{const d=document.createElement('div');d.className='t-dot'+(i===0? ' active':'');d.addEventListener('click',()=>{show(i)});dotsContainer.appendChild(d)});
}
function show(i){idx=i;quote.style.opacity=0;setTimeout(()=>{quote.textContent=testimonials[idx].text + ' ' + testimonials[idx].who;quote.style.opacity=1;updateDots();},220)}
function updateDots(){Array.from(dotsContainer.children).forEach((d,i)=>{d.classList.toggle('active',i===idx)});}
function cycle(){idx=(idx+1)%testimonials.length;show(idx)}
renderDots();show(0);
let timer=setInterval(cycle,5000);
// pause on hover
const tEl=document.getElementById('testimonial');
tEl.addEventListener('mouseenter',()=>clearInterval(timer));
tEl.addEventListener('mouseleave',()=>{timer=setInterval(cycle,5000)});
})();
</script>
</body>
</html>"} 
{"path":"shop.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Boutique — {{BUSINESS_NAME}}</title>
<style>
:root{--brand:#523b2a;--accent:#cfa36b;--muted:#666}
body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;margin:0;color:#222;background:#fffefb}
.header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid rgba(0,0,0,0.05)}
.logo{display:flex;align-items:center;gap:10px}
