.switch.on{background:var(--accent)}
.switch.on .knob{left:23px}
.small{font-size:13px;color:var(--muted)}
.comparison{font-size:18px}
</style>
</head>
<body>
<header class="header">
<div class="logo">
<div class="logoMark">S</div>
<div>
<div style="font-weight:700">{{BUSINESS_NAME}}</div>
