<div style="margin-top:6px">Shipping from {{CITY}}, {{STATE}}</div>
</footer>

<script>
// Pricing comparator (monthly vs prepaid) with animated numbers
(function(){
const switchEl=document.getElementById('subSwitch');
const display=document.getElementById('priceDisplay');
let prepaid=false;
const monthlyPrice=12; // per unit
const prepaidPrice=9;  // per unit with savings
let rafId=null;
function animateValue(start,end,duration=500){
const startTime=performance.now();
cancelAnimationFrame(rafId);
function frame(now){
const t=Math.min(1,(now-startTime)/duration);
const val = Math.round(start + (end-start)*t);
display.textContent = val;
if(t<1) rafId=requestAnimationFrame(frame);
}
rafId=requestAnimationFrame(frame);
}
switchEl.addEventListener('click',function(){
prepaid=!prepaid;
switchEl.classList.toggle('on',prepaid);
switchEl.setAttribute('aria-pressed',String(prepaid));
const from = parseInt(display.textContent,10)|| (prepaid?monthlyPrice:prepaidPrice);
const to = prepaid?prepaidPrice:monthlyPrice;
animateValue(from,to);
});
// initialize
display.textContent = monthlyPrice;
})();
</script>
</body>
</html>"} 
